CREATE TABLE IF NOT EXISTS `inventory_records` (`id` TEXT NOT NULL, `sicCode` TEXT NOT NULL, `assetType` TEXT NOT NULL, `routeCode` TEXT NOT NULL, `roadbedCode` TEXT NOT NULL, `startPrCode` TEXT NOT NULL, `startDistanceM` REAL NOT NULL, `endPrCode` TEXT, `endDistanceM` REAL, `sideCode` TEXT, `latitude` REAL NOT NULL, `longitude` REAL NOT NULL, `altitudeM` REAL, `gpsAccuracyM` REAL, `surveyDate` TEXT NOT NULL, `observations` TEXT, `status` TEXT NOT NULL, `photoSyncStatus` TEXT NOT NULL, `excelSyncStatus` TEXT NOT NULL, `createdAt` INTEGER NOT NULL, `updatedAt` INTEGER NOT NULL, PRIMARY KEY(`id`));
CREATE INDEX IF NOT EXISTS `index_inventory_records_routeCode` ON `inventory_records` (`routeCode`);
CREATE INDEX IF NOT EXISTS `index_inventory_records_sicCode` ON `inventory_records` (`sicCode`);
CREATE INDEX IF NOT EXISTS `index_inventory_records_surveyDate` ON `inventory_records` (`surveyDate`);
CREATE TABLE IF NOT EXISTS `photos` (`id` TEXT NOT NULL, `recordId` TEXT NOT NULL, `photoIndex` INTEGER NOT NULL, `localPath` TEXT NOT NULL, `isPrimary` INTEGER NOT NULL, `generatedFileName` TEXT, `driveFolderId` TEXT, `driveFileId` TEXT, `syncStatus` TEXT NOT NULL, `createdAt` INTEGER NOT NULL, PRIMARY KEY(`id`), FOREIGN KEY(`recordId`) REFERENCES `inventory_records`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE );
CREATE INDEX IF NOT EXISTS `index_photos_recordId` ON `photos` (`recordId`);
CREATE UNIQUE INDEX IF NOT EXISTS `index_photos_recordId_photoIndex` ON `photos` (`recordId`, `photoIndex`);
CREATE TABLE IF NOT EXISTS `sic17_details` (`recordId` TEXT NOT NULL, `classCode` TEXT NOT NULL, `typeCode` TEXT NOT NULL, `bridgeCode` TEXT, `inventoriedCode` TEXT NOT NULL, `spans` INTEGER, `dimension1LengthM` REAL, `dimension2LowerHeightM` REAL, `structuralConditionCode` TEXT NOT NULL, `functionalConditionCode` TEXT NOT NULL, `serviceTypeCode` TEXT NOT NULL, `singularityCode` TEXT NOT NULL, `singularityName` TEXT, `dimension3UpperHeightM` REAL, PRIMARY KEY(`recordId`), FOREIGN KEY(`recordId`) REFERENCES `inventory_records`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE );
CREATE TABLE IF NOT EXISTS `sic18_details` (`recordId` TEXT NOT NULL, `classCode` TEXT NOT NULL, `typeCode` TEXT NOT NULL, `spans` INTEGER, `crossSectionCode` TEXT NOT NULL, `dimension1M` REAL, `dimension2M` REAL, `structuralConditionCode` TEXT NOT NULL, `functionalConditionCode` TEXT NOT NULL, PRIMARY KEY(`recordId`), FOREIGN KEY(`recordId`) REFERENCES `inventory_records`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE );
CREATE TABLE IF NOT EXISTS `sic19_details` (`recordId` TEXT NOT NULL, `classCode` TEXT NOT NULL, `typeCode` TEXT NOT NULL, `crossSectionCode` TEXT NOT NULL, `structuralConditionCode` TEXT NOT NULL, `functionalConditionCode` TEXT NOT NULL, PRIMARY KEY(`recordId`), FOREIGN KEY(`recordId`) REFERENCES `inventory_records`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE );
CREATE TABLE IF NOT EXISTS `sic20_details` (`recordId` TEXT NOT NULL, `classCode` TEXT NOT NULL, `typeCode` TEXT NOT NULL, `dimension1M` REAL, `dimension2M` REAL, `structuralConditionCode` TEXT NOT NULL, `functionalConditionCode` TEXT, PRIMARY KEY(`recordId`), FOREIGN KEY(`recordId`) REFERENCES `inventory_records`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE );
CREATE TABLE IF NOT EXISTS `sic21_details` (`recordId` TEXT NOT NULL, `classCode` TEXT NOT NULL, `typeCode` TEXT NOT NULL, `materialCode` TEXT NOT NULL, `conditionCode` TEXT NOT NULL, PRIMARY KEY(`recordId`), FOREIGN KEY(`recordId`) REFERENCES `inventory_records`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE );
CREATE TABLE IF NOT EXISTS `sic22_details` (`recordId` TEXT NOT NULL, `classCode` TEXT NOT NULL, `typeCode` TEXT NOT NULL, `materialCode` TEXT NOT NULL, `signalCode` TEXT, `kilometerPostNumber` TEXT, `conditionCode` TEXT NOT NULL, `signWidthM` REAL, `signHeightM` REAL, `lowerEdgeHeightM` REAL, PRIMARY KEY(`recordId`), FOREIGN KEY(`recordId`) REFERENCES `inventory_records`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE );
